from __future__ import annotations

from functools import lru_cache
from typing import Any

from django.urls import NoReverseMatch, reverse

EntityLink = dict[str, str]
SeenKey = tuple[str, str]


def _normalize_text(value: Any) -> str:
    if value is None:
        return ""
    return str(value).strip()


@lru_cache(maxsize=None)
def _resolve_reverse(viewname: str, kwarg_name: str) -> str | None:
    """Resolve a URL pattern once per (viewname, kwarg) shape.

    Returns a template with `{id}` placeholder, or None if the route is
    unavailable. Reverse() does pattern compilation/lookup on every call; this
    cache means we only pay that once per process.
    """
    try:
        sample = reverse(viewname, kwargs={kwarg_name: "00000000-0000-0000-0000-000000000000"})
    except NoReverseMatch:
        return None
    return sample.replace("00000000-0000-0000-0000-000000000000", "{id}")


def _build_url(viewname: str, kwarg_name: str, fallback: str, entity_id: str) -> str:
    template = _resolve_reverse(viewname, kwarg_name)
    if template is None:
        return fallback
    return template.replace("{id}", entity_id)


def _build_event_link(event_id: str, label: str) -> EntityLink:
    return {
        "kind": "event",
        "id": event_id,
        "label": label,
        "url": _build_url("event_detail", "event_id", f"/events/{event_id}/", event_id),
    }


def _build_trip_link(trip_id: str, label: str) -> EntityLink:
    return {
        "kind": "trip",
        "id": trip_id,
        "label": label,
        "url": _build_url("trips:trip_detail", "pk", f"/trips/{trip_id}/", trip_id),
    }


def _append_unique(
    links: list[EntityLink],
    seen: set[SeenKey],
    link: EntityLink,
) -> None:
    key = (link["kind"], link["id"])
    if key in seen:
        return
    seen.add(key)
    links.append(link)


def _extract_from_mapping(
    *,
    value: dict[str, Any],
    links: list[EntityLink],
    seen: set[SeenKey],
    tool_name: str | None = None,
) -> None:
    event_id = _normalize_text(value.get("event_id"))
    event_label = _normalize_text(
        value.get("title") or value.get("event_title") or value.get("name")
    )
    if event_id and event_label:
        _append_unique(links, seen, _build_event_link(event_id, event_label))

    trip_id = _normalize_text(value.get("trip_id"))
    trip_label = _normalize_text(
        value.get("trip_title") or value.get("trip_name") or value.get("name")
    )
    if trip_id and trip_label:
        _append_unique(links, seen, _build_trip_link(trip_id, trip_label))

