from typing import Any

from django.urls import NoReverseMatch, reverse

EntityLink = dict[str, str]


def _normalize_text(value: Any) -> str:
    if value is None:
        return ""
    return str(value).strip()


def _reverse_or_fallback(viewname: str, fallback: str, **kwargs: Any) -> str:
    try:
        return reverse(viewname, kwargs=kwargs)
    except NoReverseMatch:
        return fallback


def _build_event_link(event_id: str, label: str) -> EntityLink:
    return {
        "kind": "event",
        "id": event_id,
        "label": label,
        "url": _reverse_or_fallback(
            "event_detail",
            f"/events/{event_id}/",
            event_id=event_id,
        ),
    }


def _build_trip_link(trip_id: str, label: str) -> EntityLink:
    return {
        "kind": "trip",
        "id": trip_id,
        "label": label,
        "url": _reverse_or_fallback(
            "trips:trip_detail",
            f"/trips/{trip_id}/",
            pk=trip_id,
        ),
    }


def _append_unique(links: list[EntityLink], link: EntityLink) -> None:
    if link not in links:
        links.append(link)


def _extract_from_mapping(
    *,
    value: dict[str, Any],
    links: list[EntityLink],
    tool_name: str | None = None,
) -> None:
    event_id = _normalize_text(value.get("event_id"))
    event_label = _normalize_text(
        value.get("title") or value.get("event_title") or value.get("name")
    )
    if event_id and event_label:
        _append_unique(links, _build_event_link(event_id, event_label))

    trip_id = _normalize_text(value.get("trip_id"))
    trip_label = _normalize_text(
        value.get("trip_title") or value.get("trip_name") or value.get("name")
    )
    if trip_id and trip_label:
        _append_unique(links, _build_trip_link(trip_id, trip_label))

    if tool_name == "read_trip_summaries":
        summary_trip_id = _normalize_text(value.get("id"))
        summary_trip_label = _normalize_text(value.get("name"))
        if summary_trip_id and summary_trip_label:
            _append_unique(links, _build_trip_link(summary_trip_id, summary_trip_label))


def _walk_entity_payload(
    value: Any,
    *,
    links: list[EntityLink],
    tool_name: str | None = None,
) -> None:
    if isinstance(value, dict):
        _extract_from_mapping(value=value, links=links, tool_name=tool_name)
        for child in value.values():
            _walk_entity_payload(child, links=links, tool_name=tool_name)
    elif isinstance(value, list):
        for item in value:
            _walk_entity_payload(item, links=links, tool_name=tool_name)


def extract_entity_links_from_tool_result(
    *,
    tool_name: str,
    tool_result: Any,
) -> list[EntityLink]:
    links: list[EntityLink] = []
    _walk_entity_payload(tool_result, links=links, tool_name=tool_name)
    return links


def extract_entity_links_from_context(context: dict[str, Any]) -> list[EntityLink]:
    links: list[EntityLink] = []
    focused_event = context.get("focused_event")
    if isinstance(focused_event, dict):
        _walk_entity_payload(focused_event, links=links)

    trips = context.get("trips")
    if isinstance(trips, list):
        _walk_entity_payload(trips, links=links, tool_name="read_trip_summaries")

    return links


def normalize_entity_links(value: Any) -> list[EntityLink]:
    if not isinstance(value, list):
        return []

    links: list[EntityLink] = []
    for item in value:
        if not isinstance(item, dict):
            continue
        kind = _normalize_text(item.get("kind"))
        item_id = _normalize_text(item.get("id"))
        label = _normalize_text(item.get("label"))
        url = _normalize_text(item.get("url"))
        if not kind or not item_id or not label or not url:
            continue
        _append_unique(
            links,
            {
                "kind": kind,
                "id": item_id,
                "label": label,
                "url": url,
            },
        )
    return links
