  function setComposerEnabled(enabled) {
    [elements.input, elements.imageInput].forEach((element) => {
      if (element) {
        element.disabled = !enabled;
      }
    });
    const sendButton = elements.composer?.querySelector('button[type="submit"]');
    if (sendButton) {
      sendButton.disabled = !enabled;
    }
  }

  function schedulePollingIfNeeded() {
    if (state.pollingTimer) {
      window.clearTimeout(state.pollingTimer);
      state.pollingTimer = null;
    }
    if (!hasPendingResponse()) {
      return;
    }
    state.pollingTimer = window.setTimeout(() => {
      void loadMessages();
    }, 2200);
  }

  function hasPendingResponse() {
    return state.messages.some((message) => {
      const runStatus = (message.run_status || '').toUpperCase();
      const messageStatus = (message.status || '').toUpperCase();
      return runStatus === 'PENDING' || runStatus === 'RUNNING'
        || (message.role === 'assistant' && messageStatus && !['COMPLETED', 'FAILED'].includes(messageStatus));
    });
  }

  function updateActiveTitle() {
    if (!elements.activeTitle) {
      return;
    }
    elements.activeTitle.textContent = getActiveThread()?.title || 'Conversation';
  }

  function getActiveThread() {
    return state.threads.find((thread) => thread.id === state.activeThreadId) || null;
  }

  function resizeComposer() {
    if (!elements.input) {
      return;
    }
    elements.input.style.height = 'auto';
    elements.input.style.height = `${Math.min(elements.input.scrollHeight, 140)}px`;
  }

  function setStatus(message) {
    if (elements.status) {
      elements.status.textContent = message || '';
    }
  }

  function showError(error) {
    setStatus(error instanceof Error ? error.message : 'Something went wrong.');
  }

  function formatDate(value) {
    if (!value) {
      return '';
    }
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) {
      return '';
    }
    return new Intl.DateTimeFormat(undefined, {
      month: 'short',
      day: 'numeric',
      hour: 'numeric',
      minute: '2-digit',
    }).format(date);
  }

  function formatStatus(value) {
    return String(value || '')
      .replace(/_/g, ' ')
      .replace(/\b\w/g, (letter) => letter.toUpperCase());
  }

  function escapeHtml(value) {
    const div = document.createElement('div');
    div.textContent = value;
    return div.innerHTML;
  }
